const output = $input.first().json;

// Extract Gemini's response text.
const raw =
  output.content?.parts?.[0]?.text ??
  output.candidates?.[0]?.content?.parts?.[0]?.text ??
  output.text ??
  output.output ??
  null;

let result;

try {
  if (raw && typeof raw === 'object') {
    result = raw;
  } else if (typeof raw === 'string') {
    const cleaned = raw
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '')
      .trim();

    result = JSON.parse(cleaned);
  } else {
    throw new Error('Gemini response text not found.');
  }

  if (
    typeof result.needs_followup !== 'boolean' ||
    typeof result.reason !== 'string' ||
    !result.reason.trim()
  ) {
    throw new Error('Invalid Gemini response structure.');
  }

  const categories = [
    'functional', 'non_functional', 'security',
    'usability', 'performance', 'stakeholder', 'constraint'
  ];

  const priorities = ['high', 'medium', 'low'];

  if (
    !categories.includes(result.category) ||
    !priorities.includes(result.priority)
  ) {
    throw new Error('Invalid category or priority.');
  }

  if (
    result.needs_followup &&
    (typeof result.followup_question !== 'string' ||
     !result.followup_question.trim())
  ) {
    throw new Error('Missing follow-up question.');
  }

  return [{
    json: {
      valid: true,
      needs_followup: result.needs_followup,
      reason: result.reason.trim(),
      followup_question: result.needs_followup
        ? result.followup_question.trim()
        : null,
      category: result.category,
      priority: result.priority,
      project_id: $('Get Answered Question').first().json.project_id,
      original_question_id: $('Get Answered Question').first().json.id,
      original_question: $('Get Answered Question').first().json.question,
      original_answer: $('Get Answered Question').first().json.answer
    }
  }];

} catch (error) {
  return [{
    json: {
      valid: false,
      error: 'INVALID_AI_RESPONSE',
      message: String(error?.message ?? error)
    }
  }];
}

